            moby->state = 0x10;
            ku = *(float *)&blarg_commando_hit_knock_up * g_frame_time;
            kb = *(float *)&blarg_commando_hit_knock_back * g_frame_time;
            moby->flags &= ~0x1000;
            vars->knock_up = ku;
            vars->knock_min = 9.0f;
            vars->knock_back = kb;
            vars->knock_max = 17.0f;
            InitKnockback(moby, vars->anim, fast_atan2(*(float *)(hit + 0x10), *(float *)(hit + 0x14)), 8, 1, 0);
            vars->flash_time = 0xFA;
